quests[39336] = { id = 39336, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Need More Powder!", description = "The substance you brought me appears to be precipitating powder, a highly volatile reagent used by the vrykul in their recipes.\n\nThere are rumors that a vrykul elder named Katterin has built up quite a store of this powder. A substance this dangerous needs to be in our hands, not hers!", progress = "Let's hope you find the powder we need...", completion = "The ghost of Svena appeared again? Seems she doesn't take kindly to our attempts to learn these vrykul recipes...\n\nThankfully, the satchel you recovered has all the precipitating powder we require for the alchemy table. Another victory for us!", objectives = "Obtain Katterin's Alchemy Kit from Katterin the Blistered in Stormheim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39337] = { id = 39337, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forlorn Filter", description = "Next on the list of things to replace are my filters. Now I'm sure you've concluded that an alchemist of my caliber uses only the finest of tools when mixing my potions.\n\nThe elves at the Temple of Elune in Val'sharah use Shaldorei silk to craft their robes. Perhaps they'd be willing to part with some for my filters.", progress = "A pile of tattered shaldorei silk lay on the chest.", completion = "This Shaldorei Silk appears to be torn into strips. The elves have apparently been using it as bandages for their fallen warriors.", objectives = "Speak with a Temple Priestess at the Temple of Elune to see if you can acquire some Shaldorei Silk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39338] = { id = 39338, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return the Filter", description = "What was torn has now been mended. I hope you put this Shaldorei silk to good use.\n\nNow, run along.", completion = "This Shaldorei Silk will make an excellent filter for the alchemy table. Nice work getting that nightborne to help us, {name}!", objectives = "Return the Mended Shaldorei Silk to Deucus Valdera in Dalaran.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39339] = { id = 39339, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fragile Crucible", description = "I have customers asking for alchemist stones, but I'm unable to make any until I replace my crucible.\n\nIn order to create a new one, we'll need a few things, but first we'll need a proper container. Something that can be augmented to withstand a demon's breath.\n\nThere's a place in Suramar which the Legion has occupied. There surely must be a device there we can take that will be suitable for our needs.", progress = "I trust you're strong enough to handle a few demons?", completion = "You've found something quite intriguing here! Others have brought me fragments of such implements, but never so complete a sample.\n\nThis is going to require a lot of work...", objectives = "Bring the Fragile Demonsbreath Crucible to Deucus Valdera in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39340] = { id = 39340, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lining the Crucible", description = "The first step in making this crucible useful is to restore the lining of its interior. That's going to require supplies you'll either gather yourself or obtain through trade with fellow adventurers.\n\nFelwort and yseralline seeds are familiar to herbalists.\n\nFelhide is obtained through skinning.\n\nBlood of Sargeras can be found all over the Broken Isles.", progress = "Restoring the lining of the crucible is no simple task, {name}.", completion = "It looks like you acquired everything we need. Give me a few moments to apply them to the interior.\n\n<Deucus works on the crucible, restoring its lining.>\n\nPerfect! The crucible is almost ready for use.\n\nJust one more tiny detail...", objectives = "Gather 1 Blood of Sargeras, 1 Felhide, 2 Felwort, and 100 Yseralline Seeds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39341] = { id = 39341, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vault of the Wardens: Demon's Bile", description = "The key to a crucible like this is that it must be bathed in the foulest of fel energy. I hate to say it, but the most efficient method of accomplishing such a feat is to subject it to the bile of a demon.\n\nYes, I said the bile of a demon. Ready to get to work?\n\nIn the Vault of the Wardens, such a demon exists. An imp mother by the name of Grimoira. The door to her room is sealed by an invisible lock.\n\nI'd suggest bringing some Skaggldrynk with you. Use it when you get to her door.", completion = "You did it! I must say, I was a bit concerned for your well-being, but once again you've proven resourceful.\n\nNow that the crucible's lining is restored and it has been bathed in demon's bile, it's ready for use on the alchemy table.\n\nWell done!", objectives = "Craft a Skaggldrynk, then go to the Vault of the Wardens and bathe the crucible in the bile of Grimoira.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39342] = { id = 39342, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Price of the Black Market", description = "I may have what you're looking for, burettes you say? Not a very common item.\n\nFor that, I require a moderate favor. Nothing too big, just a few things really.\n\nA silver hair from a high-ranking archmage... the blood of a titan, and, oh... some wine and cheese.\n\nWhat?! I have appetites that need satiating.", progress = "Don't take too long now. Who knows who else may be in the market for your precious burettes.", completion = "You got the hair?!\n\n<Ms. Xiulan laughs audibly.>\n\nOh, I wish I could have been there to see the look on his face. Nevertheless, a deal's a deal.", objectives = "Collect a Silver Hair of Khadgar, a Blood of Sargeras, 5 Kaldorei Ginger Wine and 5 Moist Azsunian Feta.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39343] = { id = 39343, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vault of the Wardens: Bendy Glass Tubes", description = "You find tubing formed from a bendable sort of glass. It appears as though Grimoira was using it to suck out the insides of her victims.\n\nIts magical properties, however, would seem ideal for use on an advanced alchemy table.", completion = "What's this you have for me, {name}? Say, these are some wondrous tubes! I bet I know a way to make them even better.\n\nI'll need you to temper these glass tubes in the fire of a dragon's breath under the light of a full moon on the equinox, then travel into the Emerald Dream and--\n\nOh, hold on. These tubes are perfect just as they are. Nevermind!\n\nSometimes I get a bit caught up in this whole adventuring business...", objectives = "Bring the Bendy Glass Tubes to Deucus Valdera in Dalaran.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39344] = { id = 39344, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Going Underground", description = "We're so close to replacing all my equipment, {name}. In order to make flasks again, we need to be able to precisely measure each ingredient.\n\nFor that, we need to replace my burette assembly. Unfortunately, burettes aren't easy to come by. We may be able to procure some though through other means by...\n\n<Deucus looks around and beckons you closer.>\n\nGoing underground, so to say. As in, the Black Market.\n\nGo see Ms. Xiulan. Mum's the word.", completion = "Well, now that we understand one another let's see what sort of arrangement we can come to.", objectives = "See Ms. Xiulan about acquiring some new burettes for Deucus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39345] = { id = 39345, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Calibration Experts", description = "It will take the cooperation of several highly skilled sorts to calibrate these burettes for a variety of substances.\n\nChemist Emmara is an old friend from the Undercity who has helped me with similar endeavors.\n\nThunder Bluff smells like a barn to me, but Jana Winterhoof is an alchemist with exacting standards.\n\nAnd while I'd never travel to Booty Bay without a lock on my wallet, Tryks Pourtrue has proven reliable and fair.", completion = "Yes, I'd say these burettes look well-calibrated.\n\nI knew those three would be meticulous. Never underestimate the value of someone who obsesses over tiny details, {name}!", objectives = "Take the Uncalibrated Malloric Burettes to skilled alchemists for calibration.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39346] = { id = 39346, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Testing the Calibration", description = "Now that you have the burettes calibrated, it's time to test them out! The only way to be sure is by crafting a sufficient quantity of a variety of potions.\n\nGlamorous work? No, but the most important reagent in alchemy is a bit of elbow grease!", progress = "The only way to be sure the burettes are working is to use them!", completion = "That's quite an armload of potions you made! I think it's safe to say that these burettes are working as intended.\n\nI'll add them to the alchemy table.", objectives = "Test the Malloric Burettes' calibration by crafting a variety of potions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39347] = { id = 39347, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Channeling Our Efforts", description = "While it's no secret my time is more valuable than... well, anyone's, I fear I must step in and help to replace my decoction conduit.\n\nYou will also play a crucial part in this, {name}, as my liaison with the blacksmiths. The thought of getting soot on my robes curls my toes.\n\nHere's a list of what we'll need done. Meanwhile I'll be out gathering the rest of what's needed.", completion = "What's this then?\n\n<Alard takes the list and looks it over. His eyes widen as he reaches the bottom>\n\nI take it you don't fully grasp what it is that you need, do you? If this is truly what's required then we better get started.", objectives = "Talk to Alard Schmied about the list of things you need done.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39348] = { id = 39348, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halls of Valor: The Prime Ingredient", description = "This first ingredient can only be obtained by visiting the next realm. Fortunately for us, there's a gate in Stormheim that can take you there.\n\nIn the Halls of Valor, there is a sand that's used for polishing their architecture. Eternity Sand, it's called. I'll need an ample amount of it as the base for the new glass.\n\nThis ingredient won't be easy to work with either. I'll need something to keep me going, you know, keep my stamina up.", progress = "What a sight the Halls of Valor must be. You'll have to tell me about them sometime after your return.", completion = "Well done, {name}. Once we have everything together, I'll get started right away.", objectives = "Retrieve the Eternity Sand from Heroic: Halls of Valor, craft a Flask of Ten Thousand Scars and return both items to Alard in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39349] = { id = 39349, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Black Rook Hold: Heavy, But Helpful", description = "The next ingredient on the list will supposedly add strength to the mix, according to Deucus. I've heard of it before, but haven't really used it.\n\nIt's called Sabelite Sulfate, and it's said the elves of Black Rook Hold use it in their blacksmithing.\n\nSomething like that won't just be lying around. You may have to delve deep into the hold to find it.\n\nAnd due to its weight, I may need a concoction of yours to compensate, something to give me a bit more strength.", progress = "I hope Deucus was right about these ingredients. This'll be the first time I'm making something like this.", completion = "<Alard takes the bag from you and peers inside.>\n\nSo this is the stuff? It's definitely true what I've heard. It is quite heavy.", objectives = "Retrieve some Sabelite Sulfate from Heroic: Black Rook Hold, craft a Flask of the Countless Armies and return both items to Alard in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39350] = { id = 39350, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maw of Souls: A Hope in Helheim", description = "For this last ingredient, well...\n\n<Alard begins pondering for a moment, then nods his head.>\n\nYes, that's the only way. For this last one, you'll need to go to the land of the damned, Helheim.\n\nWell, not there exactly, but aboard the boat that ferries the dead across the Maw of Souls. Upon that boat may be the final ingredient we need.\n\nIt's called Dragur Dust. Keep an eye out for it.\n\nAlso, one needs to be quick when adding this ingredient. I'll need something to heighten my reflexes.", progress = "Were you able to board the ship? Did you find the dust?", completion = "It was there? You found some?\n\n<Alard takes the crate and opens it. He reels back from the smell.>\n\nYep, that's the stuff alright. By the light, does that reek.", objectives = "Retrieve a crate of Dragur Dust from Heroic: Maw of Souls, craft a Flask of the Seventh Demon and return both items to Alard in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39351] = { id = 39351, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Emerald Nightmare: Rage Fire", description = "Now that we have all the ingredients assembled, we need one last thing.\n\nThe fire of my forges burn hot, but not hot enough to work these ingredients into glass. For that, we need more heat. The heat of a dragon, to be exact.\n\nI'm aware of one that has emerged from the Emerald Dream in a corrupted state. Corrupted or not, a dragon's heart burns with enough heat to melt the strongest of materials.\n\nBring me its heart and you'll have your conduit.", progress = "I'm getting the mixture ready now. As soon as you return with the heart, I'll begin the construction.", completion = "<You hand the heart over to Alard. He places it within his forge and it begins to burn white hot.>\n\nPerhaps I should refer to you as Dragonslayer {name} from now on.\n\nJoking aside, I'll begin my forging.", objectives = "Travel to the Emerald Nightmare and acquire Nythendra's Heart. Bring it to Alard in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39352] = { id = 39352, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Extinguishing the Sentinels", description = "You've made it. See that camp there? They've got some Legion Sentinels hiding in there, set to notify Sargeras any time his pet pooch gets hungry or craves attention. Shut them down.", objectives = "Extinguish the three Sentinels.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39353] = { id = 39353, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Test - New", description = "Test" }
quests[39354] = { id = 39354, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wisp in the Willows", description = "Wisps are the spirits of our night elven brethren who have become one with the forest. But their minds and the way they perceive things are very different than in life.\n\nYou should bond with this little one. See through its eyes as it travels to the hidden pools and grows some trees.", progress = "Any luck?", completion = "Oh thank you traveler! You have truly helped the forest today.", objectives = "Guide the Wisp through the Hidden Pools to grow 8 trees.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39355] = { id = 39355, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Equipment Blueprint: Trained Shark Tank", description = "This appears to be a blueprint for some sort of naval equipment.  We should take it back to our Shipyard and see if someone can decipher it.", progress = "Those look like some equipment blueprints!", completion = "This is a blueprint for some high tech naval equipment.  I should be able to reverse engineer the plans and have this equipment available for you shortly!", objectives = "Return the blueprints to a Naval Equipment Specialist at your garrison shipyard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39356] = { id = 39356, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Equipment Blueprint: High Intensity Fog Lights", description = "This appears to be a blueprint for some sort of naval equipment.  We should take it back to our Shipyard and see if someone can decipher it.", progress = "Those look like some equipment blueprints!", completion = "This is a blueprint for some high tech naval equipment.  I should be able to reverse engineer the plans and have this equipment available for you shortly!", objectives = "Return the blueprints to a Naval Equipment Specialist at your garrison shipyard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
