quests[39371] = { id = 39371, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Witches of the Sky" }
quests[39372] = { id = 39372, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Witch of the Wood", description = "You saved me at Riverbend not long ago. It is the reason I vouched for you as emissary to this tribe, and the only reason you're alive here now. I consider my debt to you paid.\n\nYou must prove yourself to the Bloodtotem chieftain before he will speak with you.\n\nWithin the forest is the Witch of the Wood, a harpy mother who recently descended into this territory. If you are able to defeat her and show her carcass to the Bloodtotem, they might allow you an audience with Torok.", completion = "The Bloodtotem don't often allow outsiders into their midst. Even asking them to give you an audience is a danger.", objectives = "Defeat the Witch of the Wood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39373] = { id = 39373, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hags of a Feather", description = "The drogbar you freed me from were unusually aggressive. The tribe in the nearby caves seems to be apart from the rest of them, but that didn't stop the Bloodtotem from going on the offensive just in case, capturing some of their number.\n\nThat move left the woods exposed to the harpies, however. Your help dealing with these witches would not go unnoticed by Torok. Bring back their feathers as proof of death.", progress = "Your size belies your strength, {name}.", completion = "I could hear them screeching from here. With this victory and the defeat of the Witch of the Wood, Torok will surely be willing to see you.", objectives = "Collect 50 Hag Feathers from Witchwood Hags in the Witchwood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39374] = { id = 39374, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Audience with Torok", description = "I should warn you that Torok is easily displeased and is hateful of outsiders. Be on your guard.\n\nWe will seek an audience with him at his tent at the Cliff's Edge. As the Rivermane Emissary here, I am afforded some protection against aggression, but they have made no such promises about you.", progress = "I just hope the Bloodtotem don't cut us down for demanding their chieftain's time.", completion = "Strange that he would be in the cavern at this time... perhaps this is a good sign?", objectives = "Speak with Torok Bloodtotem.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39375] = { id = 39375, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Short-Supply Reward" }
