quests[39380] = { id = 39380, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Short-Supply Reward" }
quests[39381] = { id = 39381, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rock Troll in a Hard Place", description = "We should leave this place while we have a chance. The Bloodtotem are amassing at their village to the north, and I believe they intend to kill my people.\n\nLet me know when you are ready to go, and I can take us to a safe place quickly.", completion = "You have little reason to trust me, but we have a common enemy in the Bloodtotem and I could use your help.", objectives = "Speak with Navarrogg to meet him at a safe location.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39382] = { id = 39382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Perrexx the Corruptor", description = "Look around you, {class}. Corruption has befouled my valley. If Malfurion requires my presence to summon Ysera the Awakened, then I will surely aid him, but not until I have purged these demons from my lands.\n\nPerrexx the Corruptor is just ahead. Help me slay this fiend.\n\nStand by my side, and together we can rout these satyrs and their brethren.", objectives = "Kill Perrexx the Corruptor in the Moonclaw Vale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39383] = { id = 39383, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dishonored", description = "Xandris the Dishonored was among the first to betray his brethren and accept the curse of Xavius.\n\nDuring the great war, it was he who led the slaughter of many of my dearest friends.\n\nThe last time I met him on the battlefield he fled. Help me to finally dispense justice on this foul being.", completion = "Xandris has finally paid for his crimes, but his blood will not bring back the innocents he has slain.", objectives = "Slay Xandris the Dishonored.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39384] = { id = 39384, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Corruptor", description = "Xandris has been slain, but there are others that must be dealt with if my grove is to be saved.\n\nDuring the great war, Kagraxxis took great pleasure in corrupting the lands he once called home.\n\nWere it not for the foolish mercy of my fellow druids, I would have slain him myself.\n\nFind the demon and bring justice upon him.\n\nI must entrust this task to you alone, for I sense an even darker presence here... one that requires my personal attention.", progress = "Kagraxxis must be slain.", completion = "You have my thanks, {class}.\n\nIf not for your arrival I would have surely perished here.", objectives = "Slay Kagraxxis the Corruptor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39385] = { id = 39385, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift for Greymane", description = "It looks like the Gilnean infiltrators brought some heavy ordnance to the fight. It's likely they intend to use them on the walls of Dreadwake's Landing.\n\nIf these could be rigged to Greymane's ship, it could make for a decisive end to his assault on the outpost.", progress = "<insert>", completion = "By the Dark Lady's favor, you did it! I witnessed the explosion from here - there's no way that Greymane could have survived such destruction! \n\nYou have done a great deed today for the Forsaken. Rest assured, it will be remembered.", objectives = "Plant 3 Gilnean Heavy Explosives onto the hull of Greymane's ship and detonate them at a safe distance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39386] = { id = 39386, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Procuring a Prototype", description = "If Addie's going to be a more permanent member of the huntin' party, then she'll need some specialty gear for someone her size.\n\nMy munitions expert should have some ideas about what kind of weapon would best suit a gnome.\n\nStop by his camp and let him know that I'll be needin' a prototype soon.", completion = "A gnome hunter, huh? Is that a joke?\n\nFine, fine. What the boss wants, the boss gets. I'll start working on a prototype as soon as I finish up my latest project.", objectives = "Find Razik Gazbolt at Icepine Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39387] = { id = 39387, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Skies of Highmountain", description = "When you are ready, join me at the base of Thunder Totem.\n\nI would be honored to have you at my side as my tribe once again swears its allegiance to the young Mayla.\n\nTogether, we are Highmountain!", progress = "Have you had any luck with Lasan?", completion = "The Skyhorn are with us? This day just got much better.", objectives = "Speak with Lasan Skyhorn at the base of Thunder Totem.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39388] = { id = 39388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moonclaw's Wisdom", description = "Our quick action today has stopped this aggression and saved my valley. As you requested, I will join Malfurion in the Grove of Cenarius.\n\nStill, there is much about these satyrs that I wish to tell you. This information would be most valuable to you.\n\nPlease meet me in my den before departing.", objectives = "Meet Thaon Moonclaw in his den.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39389] = { id = 39389, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It Hungers for Blood", description = "Bloodstones contain a great deal of power that can only be awakened once they are fed. \n\nYet this stone does not feast on fish and cakes. It hungers for blood; the more powerful, the better.\n\nThere's an infestation of demons just east of here. I need you to nourish my stone with their blood, so that I may unlock its power.", progress = "Has the Bloodstone been sated yet?", completion = "The Bloodstone looks sated. Well done! Now it's time for a test...", objectives = "Let the Bloodstone feed on the blood of demons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39390] = { id = 39390, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Mysterious Text", description = "You found a water-logged tome near the bones of a massive creature. Written in an unfamiliar language, the book is adorned with runes and alchemical symbols. Perhaps another alchemist would be able to tell you more.", progress = "You found something down in Azsuna, {name}? Do share. It's so rare for something interesting to walk through the door of my quiet little shop.", completion = "Well now, this is intriguing! This book is... well, you see, it's obviously... uh...", objectives = "Bring the Runewritten Tome to Deucus Valdera in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39391] = { id = 39391, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pet Rocks", description = "I raise creatures born of the earth to help defend myself and my people. When I was captured, I ordered them to stay behind at our home, but they are often disobedient and likely tried to follow me.\n\nIf they did, I fear the Bloodtotem may have captured them, or worse. In my current state, I can't muster the strength to find them. If you find them, it would be much appreciated.", progress = "These beasts are not terribly bright, but they are loyal in their way.", completion = "Frag has fallen? The youngest of my pets was perhaps my most dear... curse the Bloodtotem and their cruelty!", objectives = "Find Navarrogg's pets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39392] = { id = 39392, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bear Huntin'", description = "They say a single hair from the back of a bristlefur bear is sharp enough to cut a dwarf's beard. But if the fur doesn't kill ya, the maul will.\n\nSome lesser hunters have been a meal for those bears. \n\nShow me you're more than a snack and bring me back a few of those bristlefur pelts.", progress = "Procuring a few Bristlefur Pelts should help sell me on your huntin' skills.", completion = "These pelts are even sharper than I imagined. Well done, {name}.", objectives = "Collect 4 Bristlefur Pelts within the Fields of An'she.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39393] = { id = 39393, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moonclaw Vale" }
quests[39394] = { id = 39394, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cipher of Damnation", description = "Your ally and I will remove this barrier now, though it will take a greater part of our strength. What lies beyond will not be easy.\n\nGul'dan will have empowered an elemental lord with the Cipher, driving it insane. He will use it to destroy the link between the elements and Draenor. If you destroy that elemental, we could recover the Cipher.", completion = "You have saved us all. The Cipher has become fragmented with Cyrukh's death. This means its guardians can hide the shards all over Draenor so the chances of piecing it together will be impossible.\n\nThis great victory will give us more time to stop Gul'dan but I shudder to think of what his next plan may be...", objectives = "Get Oronok and your ally to destroy the barrier, then stop Gul'dan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39395] = { id = 39395, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oronok's Offer", objectives = "I am glad you trusted me, {name}. I feel like a great weight has been lifted from me.\n\nI still owe Draenor a great debt for the part I played in Gul'dan's plot. My sons will aid the shamans in rebuilding and hiding the shards. Also, if you will allow it, I want to help you remove Gul'dan from this world.\n\nI will serve you... Commander.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39397] = { id = 39397, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasion Experience Received" }
quests[39398] = { id = 39398, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Short-Supply Reward" }
quests[39399] = { id = 39399, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Panther Saberon Boss" }
quests[39400] = { id = 39400, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Panther Saberon Boss" }
quests[39401] = { id = 39401, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Destroying the Competition", description = "One battle does not win the war, Commander.\n\nThat Transport isn't gonna hold up long against this Iron Horde navy.  We are going to need another ship.  Lucky for us, a local smuggler has supplied us with the plans we need to build Destroyers.  We should construct one of these ships immediately!", progress = "What is the status of the Destroyer?", completion = "They lured us right into their trap, Commander.  I want revenge!", objectives = "Construct a Destroyer in your Shipyard and send it on a naval mission.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39404] = { id = 39404, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Destroying the Competition", description = "One battle does not win the war, Commander.\n\nThat Transport isn't gonna hold up long against this Iron Horde navy.  We are going to need another ship.  Lucky for us, a local smuggler has supplied us with the plans we need to build Destroyers.  We should construct one of these ships immediately!", progress = "What is the status of the Destroyer?", completion = "They lured us into a trap, commander.  I want revenge!", objectives = "Construct a Destroyer in your Shipyard and send it on a naval mission.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39405] = { id = 39405, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stories of Battle", description = "The writings carried by the priestess appear to be the first part of an epic poem describing the history of Ashildir, the ancient queen of the Valkyra. \n\nIf Ashildir has a connection to the shieldmaidens here, you may be able to use that to your advantage. \n\nThe answer to her involvement likely lies within the remaining text.", progress = "This appears to be the last verse.", completion = "The verses of the poem unfold the tale of Ashildir founding the shieldmaidens and bringing them to Skold-Ashil.\n\nIf these shieldmaidens revere the Valkyra queen as this would suggest, your dealings with her in Helheim may prove advantageous.", objectives = "Collect 8 verses of Ashilvara from Priestesses of Eyir in Skold-Ashil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39406] = { id = 39406, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
