quests[39416] = { id = 39416, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skoller's Bag o' Squirrel Treats" }
quests[39417] = { id = 39417, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rating Razik", description = "Hemet is expecting an update on how my munitions research and development is going.\n\nI'm sure you'll be happy to tell my boss that my latest creation worked flawlessly!\n\nYou can find him at his camp near the hunters' lodge.", completion = "It's good to hear that Razik is makin' some progress on his gadgets.\n\nMaybe if he could design a gun that aims itself, these amateurs infesting the basin would hit their targets for once.", objectives = "Find Hemet Nesingwary at his Highmountain retreat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39418] = { id = 39418, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neltharion's Lair Reward Quest" }
quests[39419] = { id = 39419, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hex-a-Gone", description = "The harpies are relentless in their pursuit to control the basin. They are able to craft bags of foul magic as quickly as we can destroy them.\n\nThe Skyhorn cannot gain the upper hand as long as their hexweaver lives. She must be stopped.", progress = "Hexweaver Akara must be slain if the Skyhorn wish to gain the upper hand.", completion = "You have done the Skyhorn a great service, {name}.", objectives = "Slay Hexweaver Akara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39420] = { id = 39420, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Xavius Event TRACKING", description = "(PH)\nDarkgrove has run out of places to hide. Now it is time to finish him off.\n\nIf we stop him now, there may be hope for this valley yet.", sourceObjective = "Defeat Botanist Darkgrove", sourceObjectiveStatus = "unverified-source-field" }
quests[39422] = { id = 39422, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shipyard Report", description = "Commander!  We have received reports from the shipyard that things are getting serious.  Can you head back to Lunarfall and check in with Merreck?  Every ship we build gives us another advantage over Gul'dan's new Horde.", completion = "We have been waiting for you, Commander.", objectives = "Return to your shipyard in Lunarfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39423] = { id = 39423, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shipyard Report", description = "Commander!  We have received reports from the shipyard that things are getting serious.  Can you head back to Frostwall and check in with Rolosh?  Every ship we build gives us another advantage over Gul'dan's new Horde.", completion = "We have been waiting for you, Commander.", objectives = "Return to your shipyard in Frostwall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39424] = { id = 39424, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Everything!" }
quests[39425] = { id = 39425, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stonedark Crystal", description = "Without my crystalline focus, my powers are weak. Those who captured me took it, and I know not where it is now.\n\nI'm sure one of the Feltotem has it. If you find it, please return it to me.", progress = "I have power over the earth without my crystal, but my power is much greater with it than without.", completion = "This will help me repair my broken body.", objectives = "Find Navarrogg's Stonedark Focus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39426] = { id = 39426, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood Debt", description = "You have proven a much greater ally than the Bloodtotem ever were. With my focus crystal, my wounds are healed. I fear Frag was too far gone to revive.\n\nTorok and his Bloodtotem will suffer for what they have done to us. Let's pay them a visit before they can mount an attack against the cave of my people.", progress = "Drogbar are not violent by nature, despite our size. But the Bloodtotem crossed us, and they pay the debt in blood.", completion = "You have earned my trust. The Stonedark are not yet safe from our brothers led by Dargrul the Underking. We would willingly join Mayla Highmountain and her tauren against them.", objectives = "Defeat Torok Bloodtotem at Torok's Bluff.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39427] = { id = 39427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eagle Spirit's Blessing", description = "The spear is linked to a spirit called Ohn'ahra. It has been tradition for us to speak with her and receive her blessing before going after the spear. She may also impart some knowledge.\n\nIf you would accompany me to Spiritwatch Point, I will summon the Eagle Spirit and ask for its blessing in the coming fight.", progress = "We've done it!", completion = "We saved the Eagle Spirit and received her blessing. I feel even more confident we will get Talonclaw now!", objectives = "Receive the Eagle Spirit's blessing at Spiritwatch Point in Highmountain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39428] = { id = 39428, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Satyr Line TRACKING", description = "(PH)\nDarkgrove has run out of places to hide. Now it is time to finish him off.\n\nIf we stop him now, there may be hope for this valley yet.", sourceObjective = "Defeat Botanist Darkgrove", sourceObjectiveStatus = "unverified-source-field" }
quests[39429] = { id = 39429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assaulting the Haglands", description = "Proceed on foot into the Haglands and slay any harpies you find.\n\nQuell their numbers!\n\nWe will provide air support and force your prey to the ground where you can deal with them.\n\nShow these witches the fury of your... well... your \"you.\"", progress = "It has been many years since we have had to enter the Haglands in force.", completion = "Haha! You are covered in the feathers of your enemies.", objectives = "Slay 8 Crawliac Harpies and 6 Skywhisker Loyalists in the Haglands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39430] = { id = 39430, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flasking for a Favor", description = "You know, this mixing flask didn't suffer terrible damage. I'm positive it can just be repaired.\n\nI'm no expert in glass repair, but I've heard of someone who is--a tauren by the name of Barm Stonebreaker. He's a smith by trade, but those who know him say he was born to work glass.\n\nThose tauren don't work for free, so you may be in for some work yourself.", progress = "You're looking for help? I hope you have something to offer my people in return, {race}.", completion = "Your gift is a noble gesture, {race}. Smithing can be a surprisingly perilous profession.\n\nNow let's see that flask.\n\n\n\nEh, that's not so bad. Give me a moment to fix it.", objectives = "Seek out Barm Stonebreaker at the Ironhorn Enclave in Highmountain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39431] = { id = 39431, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mending the Filter", description = "Bringing back the cloth in such a manner would not be beneficial to Deucus.\n\nPerhaps there's a tailor here in Val'sharah who'd be willing to mend it for you.\n\nThe priestess who helped you earlier may know of such a person.", completion = "You dare request such a menial task from me? Surely you must be joking.", objectives = "Try to find the whereabouts of a tailor in Val'sharah who can help you mend the silk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39432] = { id = 39432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unknowable Power", description = "The one they call Gul'dan has ruined his own people, and now seeks to ruin what remains of mine as well. The fallen outcasts at Kra'nak have already pledged themselves to Gul'dan in a false promise of a return to the skies. He has given the most powerful of his minions the power of the Apexis, but twisted in a way that I cannot explain. Bring one of these fragments to me.", progress = "This is simply the beginning of what you must do to save what remains of the Arakkoa.", completion = "As your archmage told me, the power that has warped these crystals comes from far beyond this world. I will need more help in discovering how to turn back the darkness inside my people.", objectives = "Collect a Fel-Corrupted Apexis Fragment from any Treasure or from any Rare or Rare Elite creature in Tanaan Jungle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39433] = { id = 39433, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unseen Influence", description = "The corruption in the Apexis has begun to affect many of my people. We are so accustomed to the power it grants us that more succumb to the whispers every day. You must bring me more samples so I can free my people from yet another curse.", progress = "I fear even your help may not be enough to avert the doom of the Arakkoa.", completion = "I will continue to need your help until this world is free of whatever terrible presence Gul'dan has invited to destroy us.", objectives = "Collect 10 Fel-Corrupted Apexis Fragments from any Treasure or from any Rare or Rare Elite creature in Tanaan Jungle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39434] = { id = 39434, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Short-Supply Reward" }
quests[39435] = { id = 39435, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oubdob da Smasher" }
quests[39436] = { id = 39436, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haglands Treasure" }
quests[39437] = { id = 39437, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deep in the Cavern", description = "We're getting tired of those murlocs. They skitter around the cavern like they own it. They stole some of our most precious relics and got their fishy fins all over them. \n\nKill a few of them so they know they don't run things around here.", progress = "Slippery little critters, aren't they?", completion = "I could hear their murlurulurls echoing in the cavern. Maybe they'll think twice before taking our stuff next time.", objectives = "Slay 8 murlocs in Stonedark Cavern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39438] = { id = 39438, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guhruhlruhlruh", description = "The murlocs are usually pretty scared of us, but some bigger one led them into our cavern and they're getting too brave.\n\nKill their leader. I think its name is something like \"Guhruhlruhlruh.\"", progress = "Can you pronounce murloc names? I never can.", completion = "That ought to send some of the murlocs packing.", objectives = "Defeat Guhruhlruhlruh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39439] = { id = 39439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stonedark Relics", description = "The murlocs managed to steal some of our sacred relics and carry them down into the lower cavern.\n\nWhile we warm up, do you think you could go find them?", progress = "We have possessed these relics for generations until the murlocs put their fishy flippers on them.", completion = "You found them! Not sure how you carried them all at one time...", objectives = "Recover the Chain of Resistance, Wheel of Fortitude, and Rod of Bearing.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39440] = { id = 39440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Lift, Brul?", description = "Do you even lift? If you can carry these weights to the statue of Liftbrul and back, maybe we can talk.", progress = "Those arms fallin' off?", completion = "Stronger than you look, little one.", objectives = "Carry the weights to the statue of Liftbrul and return to Damrul the Stronk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
