quests[39444] = { id = 39444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle At The Iron Front" }
quests[39445] = { id = 39445, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on the Fel Forge", description = "The Iron Horde continue to bring in reinforcements from all over Draenor to reinforce their position at Hellfire Citadel. If we don't cut off the flow of supplies then we risk losing control of our plans in Tanaan.\n\nA strategic attack to the supply lines at Ironhold Harbor is just the thing to keep the Iron Horde on the defensive and maintain our momentum.", objectives = "Assault the Iron Horde reinforcements at Ironhold Harbor in Tanaan Jungle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
