quests[39453] = { id = 39453, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on the Throne of Kil'jaeden", description = "The Shadow Council are summoning their demonic masters upon a mountain they are calling the Throne of Kil'jaeden. Remember the first war, we know the destruction the legion can cause if they are unchecked.\n\nHead to the Throne of Kil'jaeden and let's put an end to this invasion before it can begin.", objectives = "Assault the Shadow Council forces at the Throne of Kil'jaeden in Tanaan Jungle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39454] = { id = 39454, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on the Throne of Kil'jaeden", description = "The Shadow Council are summoning their demonic masters upon a mountain they are calling the Throne of Kil'jaeden. We know the destruction the legion can cause if they are left unchecked.\n\nHead to the Throne of Kil'jaeden and let's put an end to this invasion before it can begin.", objectives = "Assault the Shadow Council forces at the Throne of Kil'jaeden in Tanaan Jungle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39455] = { id = 39455, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cave of the Blood Trial", description = "All Bloodtotem and distinguished guests must go through a trial of blood in the cavern beneath this outpost.\n\nI hope it's a good sign that they wish you to participate in this rite of passage. You will need to show proof of your deeds, defeat a Warmonger in single combat, then perform sacrifice at an altar deep in the cavern.", progress = "Are you afraid of the dark?", completion = "They said an outsider would wield the Hammer of Khaz'goroth. I doubt you could even lift it.", objectives = "Place the Witch of the Wood's carcass on the altar and defeat a Warmonger in single combat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39456] = { id = 39456, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unexpected Allies", description = "You have gained my trust. Not all drogbar are as violent as the savages led by Dargrul the Underking, nor are all tauren as bloodthirsty as the Bloodtotem.\n\nYou may tell Mayla Highmountain that she has our support. The cavern we call home is yours to explore freely as well, {name}.", progress = "Has Torok agreed to join us?", completion = "Torok is dead? By... your hand? He must have truly given in to his thirst for blood if that came to pass.\n\nThe Stonedark on our side, though... That is an advantage I had not expected. Navarrogg has always been much more agreeable than Dargrul and his brood. Thank you for striking this rare alliance, {name}.", objectives = "Speak with Mayla Highmountain at Thunder Totem.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39460] = { id = 39460, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vale POI Event TRACKING", description = "(PH)\nDarkgrove has run out of places to hide. Now it is time to finish him off.\n\nIf we stop him now, there may be hope for this valley yet.", sourceObjective = "Defeat Botanist Darkgrove", sourceObjectiveStatus = "unverified-source-field" }
