quests[39472] = { id = 39472, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cut Out the Heart", description = "This map points out the strategic locations of the Forsaken forces around Greywatch. A marker to the east indicates an apothecary camp where Dread-Riders are being supplied from.\n\nIf you were to take out the apothecary in charge of creating this plague, it could stem the invasion and prevent the Dread-Riders from spreading the plague any further.", completion = "To think that the Forsaken were brash enough to brew their blight in our own backyard. With the loss of their apothecary, their invasion force is left without teeth. \n\nYou have done well, {name}.", objectives = "Kill Apothecary Curseheart in the Dread-Rider Incursion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
