quests[39485] = { id = 39485, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Short-Supply Reward" }
quests[39487] = { id = 39487, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crystal Fury", description = "A drogbar stonecaster known as Gelmogg entered our sacred water caverns and aims to draw its power into himself.\n\nWe must destroy him before he gets too powerful.\n\nHe is in the upper caverns.", progress = "The drogbar used to control only earthen magic, but it seems they've found a way to draw power from other sources.", completion = "I have never seen a drogbar transform like that. The Hammer of Khaz'goroth is indeed powerful.", objectives = "Slay Gelmogg.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39488] = { id = 39488, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Balance of Elements", description = "The drogbar place their foul crystals in our cave to absorb the magic within, and then they collect them when they are saturated with power.\n\nWe must recover the crystals so the magic might dissipate and be suffused back into the waters, or else the drogbar will find ways to corrupt the magic to their own purposes.", progress = "I believe the drogbar are learning stronger magic now that they have possession of the Hammer of Khaz'goroth.", completion = "With the magic now spreading back into the cave, the balance of elements will be restored and the drogbar will not last long here.", objectives = "Recover 10 Empowered Crystals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39489] = { id = 39489, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invading Spelunkers", description = "The drogbar and their earthen furies have overrun the cavern. They're perverting the magic within and destroying the elementals that have forever dwelled in this place.\n\nLet's work together to remove them from this sacred cave.", progress = "We must cleanse the cavern of the drogbar.", completion = "The cave is nearly restored...", objectives = "Slay 7 Drogbar Manathirsters or Violent Crageaters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39490] = { id = 39490, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infestation", description = "Those bugs are destroying our crops and attack any of us who get near them.\n\nWould you exterminate some of those vile creatures?", completion = "With fewer of those insects out there, I can tend to some of the crops.", objectives = "Slay 10 Diseased Grubs and 3 Overgrown Larva at Earthmother's Bounty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39491] = { id = 39491, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ormgul the Pestilent", description = "We've lived at peace with the drogbar for years--our tribe even more than the others. But we were betrayed in our last trade with them at Riverbend.\n\nThey usually supply us with potent alchemy to prevent insects from infesting our fields. This time, led by Ormgul, they have attacked the crops that sustain us all.\n\nOrmgul the Pestilent is the one who brought the infection to our farmland. Destroy him, and bring me whatever he uses to attract the bugs to our land.", progress = "The Rivermane are a peaceful tribe. We provide the others with food and healing in exchange for protection and equipment.\n\nWhen pressed, however, I am willing to put my magic to more violent use.", completion = "Now we have what they used to spray our fields. I wonder what use we could put this to...", objectives = "Slay Ormgul the Pestilent and acquire his Bug Sprayer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39493] = { id = 39493, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pinerock Basin Treasure" }
quests[39494] = { id = 39494, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Highmountain - Treasure 008 - Pinerock Basin" }
quests[39495] = { id = 39495, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hidden No More", description = "Now that you've uncovered the demons, I can sense them, too. Specifically, I sense a very powerful fel lord deeper in the cave. You need to grab his power while you still can.\n\nIf you can deal with their leader, we will take care of the rest of his forces in that cave.", completion = "Excellent. You've absorbed that fel lord's power and become more powerful in-turn.\n\nNow, we can fully concentrate on destroying the Legion and their Brood Queen.", objectives = "Kill Fel Lord Caza and take his fel power.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39496] = { id = 39496, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Flow of the River", description = "We can leave Farmer Maya in charge of the farmland now that the greatest threat has been reduced.\n\nBut we aren't out of hot water just yet, {name}. The fisheries are just as important as our fields, and they are in even greater danger than the farm if what Angler Creel says is true.", completion = "I'm glad you arrived when you did. The drogbar are increasing their aggression as we speak.", objectives = "Meet with Angler Creel in Whitewater Wash.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39497] = { id = 39497, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogre Waygate" }
quests[39498] = { id = 39498, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "High Water", description = "Riverbend! Is that what the Underking said?\n\nThat is my home and the place where we store our winter supplies. We must make it there at all speed and warn them.\n\nMeet me there.", completion = "It would seem we beat the Underking here.", objectives = "Speak with Jale Rivermane at Riverbend.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39499] = { id = 39499, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Well of Souls", description = "As you defeat Gul'dan's minions, his hold over this fel citadel weakens, allowing me to teleport you and your allies deeper into the dark halls. If I only I had some Soul Remnants - four of them, let's say - none of this would be necessary, and I could harness that power to send you directly into the upper reaches of the Citadel.", progress = "Did you manage to find any of those Soul Remnants I mentioned?", completion = "A-ha! Soul Remnants!\n\n<Khadgar cradles the Remnants briefly and focuses intently upon them.>\n\nThere, now you and your companions may access the upper level of the Citadel directly.", objectives = "Collect 4 Soul Remnants from Gorefiend in Hellfire Citadel on Normal difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39500] = { id = 39500, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Well of Souls", description = "As you defeat Gul'dan's minions, his hold over this fel citadel weakens, allowing me to teleport you and your allies deeper into the dark halls. If I only I had some Soul Remnants - four of them, let's say - none of this would be necessary, and I could harness that power to send you directly into the upper reaches of the Citadel.", progress = "Did you manage to find any of those Soul Remnants I mentioned?", completion = "A-ha! Soul Remnants!\n\n<Khadgar cradles the Remnants briefly and focuses intently upon them.>\n\nThere, now you and your companions may access the upper level of the Citadel directly.", objectives = "Collect 4 Soul Remnants from Gorefiend in Hellfire Citadel on Heroic difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39501] = { id = 39501, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Well of Souls", description = "As you defeat Gul'dan's minions, his hold over this fel citadel weakens, allowing me to teleport you and your allies deeper into the dark halls. If I only I had some Soul Remnants - four of them, let's say - none of this would be necessary, and I could harness that power to send you directly into the upper reaches of the Citadel.", progress = "Did you manage to find any of those Soul Remnants I mentioned?", completion = "A-ha! Soul Remnants!\n\n<Khadgar cradles the Remnants briefly and focuses intently upon them.>\n\nThere, now you and your companions may access the upper level of the Citadel directly.", objectives = "Collect 4 Soul Remnants from Gorefiend in Hellfire Citadel on Mythic difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39502] = { id = 39502, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fel Spire", description = "This would all be so much simpler if we could just teleport directly to the top of the Citadel, where Gul'dan works his dark magic, wouldn't it? But while demonic power fills the halls, my magic cannot penetrate to such heights.\n\nIf only I had powerful Fel Essences to work with, I could attune my magic to their defenses and bypass them. But the only place you might find such concentrated fel energy would be atop the Citadel itself. What a conundrum....", progress = "Have you been to the top of the Citadel so that I can send you to the top of the Citadel?", completion = "You did it!\n\nStrange, these Fel Essences bear the unique signature of the pit lord Mannoroth.... How in the world did you manage to... It's almost like you've been here before!\n\n<Khadgar peers at you curiously.>\n\nNo matter! With this power, I can send you and your companions straight to the top of the Citadel!", objectives = "Collect 4 Fel Essences from Mannoroth in Hellfire Citadel on Normal difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39503] = { id = 39503, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Highmountain - Treasure 011 - Pinerock Basin" }
quests[39504] = { id = 39504, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fel Spire", description = "This would all be so much simpler if we could just teleport directly to the top of the Citadel, where Gul'dan works his dark magic, wouldn't it? But while demonic power fills the halls, my magic cannot penetrate to such heights.\n\nIf only I had powerful Fel Essences to work with, I could attune my magic to their defenses and bypass them. But the only place you might find such concentrated fel energy would be atop the Citadel itself. What a conundrum....", progress = "Have you been to the top of the Citadel so that I can send you to the top of the Citadel?", completion = "You did it!\n\nStrange, these Fel Essences bear the unique signature of the pit lord Mannoroth.... How in the world did you manage to... It's almost like you've been here before!\n\n<Khadgar peers at you curiously.>\n\nNo matter! With this power, I can send you and your companions straight to the top of the Citadel!", objectives = "Collect 4 Fel Essences from Mannoroth in Hellfire Citadel on Heroic difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
