quests[39565] = { id = 39565, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rumble in the Jungle", description = "Dem fancy cat-men gotta be shown who is da boss 'round dese parts. Kill all their champions, and ya will earn da respect of all creatures in da jungle.\n\nY'gonna need dese totems to draw dem out.", progress = "No lie mon - if I'd had money on you coming back in one piece, I'd be out that money right now.", completion = "Ya done good, mon. We gotta keep up da pressure.", objectives = "Defeat the three arena champions of Fangri'la.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39566] = { id = 39566, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Search for Knowledge", description = "While you were out gallivanting, did you notice any lost relics around Azsuna? My sources tell me there are treasures to be found. These rumors merit investigation!", completion = "A sodden, aged tome lies partially buried in the muck.", objectives = "Look for ancient relics on the shoreline of Azsuna.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39567] = { id = 39567, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloodied Blades of Zeth'Gol", description = "The Bleeding Hollow clan is infamous for their blood rituals. The brutes carve sigils into their flesh and create potions from the blood of their strongest warriors.\n\nThe curved ceremonial blades they use have a power all their own. Gather some of these for me. We will deprive them of these weapons and learn something about our enemy at the same time.", progress = "We draenei have had little contact with the Bleeding Hollow before this war. They were an insular clan living in one of the most hostile parts of Draenor.", completion = "What terrible instruments these are! We will learn what we can from these and then destroy them.", objectives = "Collect 25 Bleeding Hollow Ritual Blades from Bleeding Hollow orcs in Zeth'Gol.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39568] = { id = 39568, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Little Wetwork", description = "The shattered remnants of the Iron Horde pour into Tanaan through Ironhold Harbor. If we knew more about their fleet we could dispatch countermeasures from your shipyard in Shadowmoon.\n\nPerhaps you could gather some naval intelligence for our cause?", progress = "The Prophet said it was always wise to know one's enemy before engaging.", completion = "Wonderful, wonderful. I'll send a messenger to your shipyard with the information we learned. Thank you, commander.", objectives = "Collect 15 Iron Horde Naval Manifests from forces in Ironhold Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39569] = { id = 39569, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking Their Fel Bonds", description = "Gul'dan's fel poison turns already ferocious orcs into hateful, vicious creatures with no soul. But were he here to guide us, Prophet Velen wouldn't give up on the whole race. If you could find samples of their blood, maybe we can reverse the process?\n\nYou'll find fel orcs all over Tanaan, but the Iron Front, the Fel Forge, and the Throne of Kil'jaeden are the most densely populated.", progress = "Were you able to secure some blood samples? I will not inquire as to your methods, commander.", completion = "Thank you, commander. Our scholars will study these samples at once!\n\nWe mustn't give up hope. Our eredar brothers are seemingly lost forever, but orcs from the world of Azeroth managed to break free from the Burning Legion....", objectives = "Collect 20 Vials of Fel Blood from fel orcs throughout Tanaan Jungle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39570] = { id = 39570, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets of the Shadow Council", description = "Gul'dan has been building a spy network for himself - the so-called \"Shadow Council\". As they struggle to control Tanaan, the Shadow Council has grown careless. Their members are out in the open, recruiting arakkoa at the Ruins of Kra'nak or summoning demons at the Throne of Kil'jaeden.\n\nFind members of the Shadow Council and acquire any intelligence they were foolish enough not to destroy!", progress = "What have you learned?", completion = "Yes, yes, so many papers... Ah, some of this is in code. It's all very crude, though. Our scholars will learn much from this. Well done commander!", objectives = "Collect 20 Shadow Council Missives from Shadow Council representatives in the Ruins of Kra'nak or the Throne of Kil'jaeden.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39571] = { id = 39571, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disarming Sha'naar", description = "Draenei at the Temple of Sha'naar would mine these mountains for perfect crystals to power our arcane devices. Sadly, the temple is lost to us - we have been betrayed by the Sargerei.\n\n{name}, it is imperative that you venture into those mines and secure those crystals before the Sargerei use them in their demonic rituals. If you must kill our former brothers and sisters, so be it.", progress = "That temple was once a place of peace and solitude. I fear it is forever corupted.", completion = "Very good, {name}. Our scholars will be able to use these crystals to protect and empower our people.", objectives = "Collect 8 Unrefined Draenic Crystals from the mines located within the Temple of Sha'naar in Tanaan Jungle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39572] = { id = 39572, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moozy's Adventure", description = "<Moozy is floating down the river and must be reunited with his mother.>", completion = "Moozy! Thank the spirits you are okay! Oh thank you for returning him to me. Thank you!", objectives = "Bring Moozy to Sella Waterwise at Whitewater Wash.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39573] = { id = 39573, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harnessing Their Power", description = "We have always believed that the primal creatures of Draenor could not be tamed. And yet, the Iron Horde found a way to weaponize the gronn. It would be to our advantage to learn how.\n\nVenture to the Iron Front, slay a Wargronn, and retrieve its harness. You may want to find help.", progress = "Exarch Maladaar reports that the battlefield is in chaos. Were you able to persevere?", completion = "My word, that device is enormous. Thank you for carrying it all the way back here.\n\nThere is so much my people can still learn about this world!", objectives = "Collect a Wargronn Harness from an Iron Wargronn at the Iron Front in Tanaan Jungle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39574] = { id = 39574, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pressing the Attack", description = "Gul'dan's minions are on the run, commander! If you have the strength, now would be an opportune time to press forward and assault some of his other strongholds.", progress = "Be wary of the jungle, commander.", completion = "This is wonderful news, commander. We will soon have Gul'dan's ghoulish citadel completely surrounded!", objectives = "Complete 2 bonus objective areas within Tanaan Jungle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39575] = { id = 39575, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path of Huln", description = "Armies are vital to the success of a war. But so are symbols.\n\nFor our people, few things make for a better symbol than the blessings of our most eldest ancestors.\n\nMayla must walk the Path of Huln.\n\nThe path is dangerous, and she may only bring two people with her: a spiritwalker to guide her and a champion to protect her.\n\nWill you be the champion?", completion = "Quite a drop. Mind yourself in here, this is not a safe place.", objectives = "Follow Spiritwalker Ebonhorn on the Path of Huln.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39576] = { id = 39576, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echoes of Deathwing" }
quests[39577] = { id = 39577, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Ancient Secret", description = "Before Mayla may be pronounced High Chieftain, there is one more vision she must see. I wish to show you as well.\n\nIt is an ancient secret, handed down along the Highmountain bloodline. I ask for your discretion in keeping it that way.", completion = "That day, the hammer freed me of the corruption of the Black Dragonflight.\n\nIn gratitude, I have faithfully served the Highmountain family since Huln rescued me from this pit.\n\nIt has been my honor and my pleasure to watch each of his descendants earn the title of High Chieftain.", objectives = "Assist Spiritwalker Ebonhorn in Neltharion's Vault.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39578] = { id = 39578, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Titanic Showdown", description = "The tale of Huln did not end with him acquiring the Hammer of Khaz'goroth.\n\nNo. For that part, we must venture deeper into this cavern. A final brazier awaits us ahead.\n\nCome, let us see what happened next.", completion = "And so Huln cast out Deathwing into the land of Deepholm and claimed the Hammer of Khaz'goroth as his charge.\n\nBut there was one last bit of business for him to attend to...", objectives = "Find and aid the spirit of Huln Highmountain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39579] = { id = 39579, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Backdoor", description = "This will take Mayla some time to adjust to.\n\nThat being said, we should return to Thunder Totem.\n\nJust south of here is a tunnel that should take us through the old drogbar slave enclave and then to an opening beyond.\n\nWe keep a small Skyhorn outpost there to watch and ensure nothing enters or leaves this vault without us knowing about it. They should be able to fly us back.", completion = "I always thought it odd that Ebonhorn never seemed to age. Or at least, he always looked old, but he never got older.", objectives = "Escape the Vault.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39580] = { id = 39580, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The High Chieftain", description = "I understand what Ebonhorn has been trying to tell me for a while now.\n\nOur people do not need a hammer, we need a leader. One willing to stand against any threat, even if they are terrified to do so.\n\nAnd between you and me, I am definitely terrified, but resolved.\n\nLet us return to Thunder Totem and prepare ourselves for war.", completion = "Even without the hammer, I know what to do next. When our forces are rallied, we can take the fight to the Underking.", objectives = "Speak with Mayla Highmountain at Thunder Totem.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39581] = { id = 39581, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demonslayer of Tanaan", description = "Demons! Hate 'em!\n\nGul'dan is spinning up more summoning portals with each passing hour. There's only one way to stem the tide, {name}.\n\n<Parvink smashes her gauntleted fist against her open palm.>\n\nSmash 'em!\n\nThe Temple of Sha'naar is a good place to start, or head up to the Throne of Kil'jaeden if you're looking for a real challenge.", progress = "<Parvink looks at some hatch marks she scribbled on a scrap of paper.>\n\nI'm up to 17 demons killed today. You?", completion = "Nice! You're quite the slayer, {name}. Gimmie a low-five!", objectives = "Slay 20 demons in Tanaan Jungle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39582] = { id = 39582, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tooth and Claw", description = "These wimps lugging wood around the jungle keep talking about how dangerous it is. You know, between the ravager den to the south or the raptors that stalk Zorammarsh - hey, even the beach creatures or podlings have teeth!\n\nWhat do you say you and I do a little hunting? Collect teeth from wild beasts. The bigger the beast, the more teeth. Meet me back here and we'll compare our haul!", progress = "Ready to compare notes?", completion = "<Parvink is covered in bleeding scratches and shredded leaves.>\n\nHey, not bad! We'll call it a tie. This jungle don't scare me for nothin'.\n\nMaybe we can hunt some more tomorrow?", objectives = "Collect 100 Tanaan Jungle Teeth from the various wildlife within Tanaan Jungle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39586] = { id = 39586, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringing Down the Iron Horde", description = "Ever since we humiliated 'em at Blackrock Foundry, the Iron Horde has been on the run. Gul'dan is converting them all into fel orcs, but I ain't scared. A bloodlusting orc is twice as strong but twice as stupid.\n\nHey! Let's wade into the battlefields of Tanaan and lay waste to as many orcs as we can. Orc or fel orc - doesn't matter to me.", completion = "<You and Parvink compare stories of your battles throughout the jungle. Finally, she hollers:>\n\nGLORY TO THE ALLIANCE!!\n\n<...Loud enough to frighten birds from the trees.>", objectives = "Slay 25 Iron Horde orcs in Tanaan Jungle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39588] = { id = 39588, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Will Pay With Blood", description = "The tauren go too far. I did not escape their outpost for fear that they would attack the cave and slaughter my people.\n\nIt looks like they planned to do it all along. Slay some of the Feltotem. Thin the herd.", progress = "These tauren have always been bloodthirsty. The Highmountain chieftain has barely been able to stop them killing all of us.", completion = "Their numbers are fewer, but still they threaten our safety.", objectives = "Slay 10 Feltotem Tauren.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39589] = { id = 39589, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Mysterious Summons", description = "{class}, heed my call. I am aware that you come to Stormheim seeking the Aegis of Aggramar. \n\nKnow that this will be a monumental task.\n\nHowever, I see promise in you, and thus will guide you through the ancient trials. I must warn you that no mortal has passed even the first of these trials in the recorded history of Stormheim, though countless champions have tried.\n\nIf you believe yourself worthy, outsider, seek me outside Aggramar's Vault. Your first test will await you there.", sourceObjective = "Meet Havi outside of Aggramar's Vault.", sourceObjectiveStatus = "unverified-source-field" }
quests[39590] = { id = 39590, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ahead of the Game", description = "The watcher Yotnar keeps the vault, and he is a fickle one. Challengers come from far and wide seeking the trials, but the watcher chooses not to see.\n\nIf you wish to catch his eye, show him you are worth being seen.\n\nSome of these challengers await in camps throughout the Valley of the Sword. Bring their heads to Yotnar, so that he may see them, and you.", progress = "An ironic gift you bring me, challenger.", completion = "It is a shame to see the first worthy challenger for the Aegis treating the trials with such disrespect. Such hubris cannot win the Aegis, for the gods will surely strike him down for his arrogance.\n\nYou, however, seem different. You have shown that you are a worthy challenger. \n\nI will allow you to begin the trials.", objectives = "Collect the heads of the Gutspill, Rumblehoof, and Felskorn champions in Valley of the Sword.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39591] = { id = 39591, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Trial of Valor", description = "To seek the Aegis of Aggramar, a champion must complete three great trials before riding into glorious battle through the Gates of Valor. Here you will find the knowledge of the trials you must seek out, as well as the first challenge you must face.\n\nAbove us, adorning the central plateau, you will find the archive for the Trial of Valor. Seek it out, and learn where your path leads.", completion = "You have learned of the obstacles you must face. \n\nDo you still wish to continue?", objectives = "Power up the archive device and view the holographic record for the Trial of Valor in the Terrace of the Watchers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39592] = { id = 39592, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Trial of Will", description = "Upon the highest point of the plateau above, you will find the archive device for the Trial of Will. Seek it out to learn what awaits you in Thorim's Peak. \n\nBe on your guard, outsider. The one called Skovald has left behind many of his army, and they will no doubt be unfriendly.", completion = "The knowledge you've gained is a powerful tool to use against your foes. \n\nDo not forget this.", objectives = "Power up the archive device and view the holographic record for the Trial of Will in the Terrace of the Watchers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39593] = { id = 39593, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shattered Watcher", description = "When your adversary - the one called Skovald- completed his first trial, he used his ill-begotten powers to sunder my physical body.\n\nI cannot allow a contender to pass through the vault while I remain unwhole. \n\nHis forces have no doubt scattered my pieces through the plateau which they currently desecrate. Bring them back to me, so that I may properly guide your trial.", progress = "Have you managed to find them all?", completion = "Wonderful! \n\nIt is good to be whole again!", objectives = "Collect the pieces of Yotnar's body from the Terrace of the Watchers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39594] = { id = 39594, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Trial of Might", description = "I owe you my gratitude for helping make me whole again, outsider. It is clear that you are worthy to take on the trials. \n\nGo now into the vault. There you will find the archive for the first trial you must undertake.\n\nI will meet you inside.", completion = "The trial is done, and you emerge victorious! \n\nIt is a great feat you have done here, but you are not through yet. Many great challenges await you on your path to the Aegis.", objectives = "Activate the archive device to learn about the Trial of Might.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39595] = { id = 39595, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood and Gold", description = "The challengers gathered in the Valley of the Sword have brought with them offerings to the watchers of the vault. \n\nIt might be a good idea to take some of these offerings with you to help in appeasing Yotnar.", progress = "What is this you bring?\n\nYou honor me, outsider.", completion = "I appreciate your gifts, outsider. You show great respect to the trials. \n\nYou do well to honor our ways.", objectives = "Collect 7 Challenger's Tributes from Valley of the Sword.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39596] = { id = 39596, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Val'sharah - Vale - Vignette: Perrexx - TRACKING - twh" }
quests[39597] = { id = 39597, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blessing of the Watchers", description = "As is your due for passing the Trial of Might, I will grant you the blessing of the watchers. \n\nFurthermore, to aid you in your trials to come, I will bestow upon your artifact the power of the vault's keeper. May it serve you well in your time of need.\n\nSpeak to me when you are ready to receive this gift.", completion = "The trial is done and you yet live. This land is full of wonders, yes?\n\nBut it looks like the God-King intends to give you trials on top of trials. Still you must hurry, for even now, the next awaits!", objectives = "Speak to Yotnar to receive the blessing of the watchers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39601] = { id = 39601, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Sunk Your Battleship", description = "Commander, we must expand our fleet if we hope to stand a chance against the Iron Horde.\n\nWe have heard reports from Tanaan that a new Alliance faction can supply us with the plans to build battleships.  Head out there as soon as you can and investigate!", progress = "Any luck with those battleship plans?", completion = "I look forward to seeing your impressive fleet of battleships, commander.", objectives = "Meet Vindicator Krethos at Lion's Watch in Tanaan Jungle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39602] = { id = 39602, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where's Lyndras: Sewer Sleuthing", description = "Linzy said that Lyndras escaped down into the sewers of Dalaran. Surely there must be a clue down there as to his whereabouts.\n\nHopefully he hasn't caused any more commotion amongst the citizens of Dalaran.", objectives = "Search the sewers for clues as to where Lyndras has gone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39604] = { id = 39604, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Sunk Your Battleship", description = "Commander, we must expand our fleet if we hope to stand a chance against the Iron Horde.\n\nWe have heard reports from Tanaan that a new Horde faction can supply us with the plans to build battleships.  Head out there as soon as you can and investigate!", progress = "Any luck with those battleship plans?", completion = "I look forward to seeing your impressive fleet of battleships, commander.", objectives = "Meet Shadow Hunter Denjai at Vol'mar in Tanaan Jungle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39605] = { id = 39605, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where's Lyndras: Downward Spiral", description = "Flitz mentioned a manhole near Violet Hold, perhaps that would be the best place to pick up Lyndras' trail.", completion = "The trail ended at Linzy's ley flame burner, lying in pieces upon the ground.\n\nThere are too many guards around for this to have gone unnoticed. Perhaps they have some information about Lyndras.", objectives = "Continue following Lyndras' trail.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
